Translate("esMX", "first-mate-fitzsimmons", {
	title = "Primer oficial Fitzsimmons",
	subtitle = "Último superviviente de la Tercera Flota",
	found = "Mesón Aguahonda, Puerto de Menethil",
	hint = [=[Invite a una copa al marinero que ahoga sus recuerdos en el Mesón Aguahonda.]=],
	allegiance = "Kul Tiras (antes)",
	aliases = { "Fitzsimmons" },
	sections = {
		{
			title = "Resumen",
			text = [=[Fitzsimmons era primer oficial del {i}Wave Mistress{/i}, un navío de línea de la {link:third-fleet}Tercera Flota{/link} de {link:kul-tiras}Kul Tiras{/link}. En el último viaje de la flota, dragones rojos montados por orcos cayeron sobre ella y la quemaron frente a la costa de {link:wetlands}Los Humedales{/link}. Solo él sobrevivió. Ahora pasa los días en el Mesón Aguahonda, oliendo a agrio y sediento, y las noches soñando con sus hermanos ahogados.]=],
		},
		{
			title = "Importancia",
			text = [=[Fitzsimmons es la memoria viva de {link:third-fleet}la Flota Condenada{/link}. Solo él sabe que algo terrible se ocultaba a bordo de uno de sus barcos, y que su poder impide descansar a los muertos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Cuenta la historia de la {link:third-fleet}Tercera Flota{/link} a cualquiera que le invite a hidromiel.
• Pide que liberen a sus hermanos malditos.
• Envía a los buscadores ante el fantasma del capitán {link:captain-halyndor}Halyndor{/link} en pos de la llave del cofre del barco.
• Indica el camino hacia el Greenwarden, y advierte al buscador de que no vaya.]=],
		},
	},
	chapters = {
		{
			title = "La Flota Condenada",
			hint = [=[Suelte la lengua del viejo marinero con una jarra de hidromiel.]=],
			text = [=[Con una copa nueva en la mano, Fitzsimmons lo cuenta sin rodeos. La flota zarpó; llegaron los dragones; los barcos ardieron y se hundieron. No sabe por qué sobrevivió. Maldice a su capitán por llevarlos a la perdición, y bebe por sus hermanos en sus tumbas de agua.]=],
		},
		{
			title = "El Ojo maldito",
			hint = "Abra el cofre del Intrepid.",
			text = [=[El capitán {link:captain-halyndor}Halyndor{/link} había guardado la cosa bajo llave en su cofre a bordo del {i}Intrepid{/i}. Cuando se abrió el cofre, contenía un orbe ennegrecido que latía con una luz enfermiza: un Ojo de Paleth, corrompido por el dolor que había presenciado. Fitzsimmons no quiso tocarlo. Se lo envió al sacerdote {link:glorin-steelbrow}Glorin Steelbrow{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:third-fleet}La Tercera Flota{/link}" },
		{ text = "La tripulación maldita" },
		{ text = "Levantar la maldición" },
		{ text = "{link:rethiel-the-greenwarden}El Greenwarden{/link}" },
	},
	bonds = {
		{ id = "captain-halyndor", name = "Capitán Halyndor", note = "su antiguo capitán, al que culpa" },
		{ id = "glorin-steelbrow", name = "Glorin Steelbrow", note = "recibió el Ojo" },
		{ id = "rethiel-the-greenwarden", name = "Rethiel el Greenwarden", note = "el espíritu del que advierte" },
	},
})

