			text = [=[Sida no dice por qué visita la tumba ni qué guardaba en su bolsa. El curtidor {link:james-halloran}James Halloran{/link} pensó una vez en enviar a su esposa a hablar con ella, aunque no dijo por qué.]=],
		},
	},
	mentions = {
		{ text = "Rebuscar en el cieno" },
		{ text = "Entrega diaria" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "un vecino que habla de ella" },
	},
})

