Translate("esMX", "archaeologist-flagongut", {
	title = "Arqueólogo Flagongut",
	subtitle = "Erudito de la Liga de Expedicionarios",
	found = "Mesón Aguahonda, Puerto de Menethil",
	hint = [=[Busque al arqueólogo que espera en el Mesón Aguahonda una escolta hasta la excavación.]=],
	allegiance = "Liga de Expedicionarios",
	aliases = { "Flagongut" },
	sections = {
		{
			title = "Resumen",
			text = [=[Flagongut es un arqueólogo de la {link:explorers-league}Liga de Expedicionarios{/link}. En una de las conferencias de la Liga en {link:ironforge}Forjaz{/link}, mostró un fósil que creía que guardaba un poder oculto. Encontró una reliquia, la Piedra de Relu, que pensaba que podía liberarlo. De camino a la excavación de {link:prospector-whelgar}Whelgar{/link}, unos raptores lo atacaron y uno de ellos se tragó la piedra. Desde entonces espera una escolta en el Mesón Aguahonda.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudia los fósiles de la excavación de {link:prospector-whelgar}Whelgar{/link} y de {link:remtravel-s-excavation}la excavación de Remtravel{/link} en {link:darkshore}Costa Oscura{/link}.
• Busca la Piedra de Relu, perdida en el vientre de un raptor moteado.]=],
		},
	},
	chapters = {
		{
			title = "La Piedra de Relu",
			hint = "Lleve al arqueólogo ambos fósiles y la piedra.",
			text = [=[Con la piedra y los dos fósiles ante él, Flagongut se puso a trabajar. Lo que le respondió no fue un simple secreto del pasado. Se invocó un espíritu, y él gritó maravillado.]=],
		},
	},
	mentions = {
		{ text = "El prospector despistado" },
		{ text = "El prospector despistado" },
	},
	bonds = {
		{ id = "prospector-whelgar", name = "Prospector Whelgar", note = "tiene el fósil original" },
		{ id = "prospector-remtravel", name = "Prospector Remtravel", note = "encontró el otro fósil" },
		{ id = "archaeologist-hollee", name = "Arqueóloga Hollee", note = "le envió el fósil de Remtravel" },
	},
})

Translate("esMX", "tarrel-rockweaver", {
	title = "Tarrel Rockweaver",
	subtitle = "Esposo de la excavación",
	found = "El camino al norte del Puerto de Menethil",
	hint = [=[Busque al enano preocupado que espera cartas a las afueras de Menethil.]=],
