	},
	mentions = {
		{ text = "En busca del equipo de excavación" },
		{ text = "En busca del equipo de excavación" },
		{ text = "Amor no correspondido" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "su esposa" },
		{ id = "archaeologist-hollee", name = "Arqueóloga Hollee", note = "su antigua compañera de estudios" },
	},
})

