Translate("esMX", "prospector-whelgar", {
	title = "Prospector Whelgar",
	subtitle = "Jefe de la excavación de Los Humedales",
	found = "El risco sobre la Excavación de Whelgar",
	hint = [=[Busque al viejo prospector que dirige la excavación de la Liga de Expedicionarios en Los Humedales.]=],
	allegiance = "Liga de Expedicionarios",
	aliases = { "Whelgar" },
	sections = {
		{
			title = "Resumen",
			text = [=[El prospector Whelgar dirige la excavación de la {link:explorers-league}Liga de Expedicionarios{/link} que lleva su nombre. Es viejo, demasiado viejo, dice, para bajar entre las bestias que se han adueñado de su campamento. Pero su mente es aguda. Justo antes de que llegaran los raptores, desenterró una gran tablilla, la {link:goaz-stone}Piedra de Goaz{/link}, tallada en la escritura de los titanes y rota en cuatro partes. Cree que los fragmentos que faltan guardan la clave de un misterio mayor que cualquiera que haya hallado la Liga.]=],
		},
		{
			title = "Importancia",
			text = [=[La tablilla de Whelgar habla de un plan divino y de una profecía condenada, y de Dioses Antiguos encadenados bajo la tierra. Pocos hallazgos de la Liga han tocado cosas más antiguas o más oscuras.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Tiene el fósil original que el arqueólogo {link:archaeologist-flagongut}Flagongut{/link} desea estudiar.
• Sobrevivió al ataque de los raptores contra su excavación junto a {link:merrin-rockweaver}Merrin Rockweaver{/link} y {link:ormer-ironbraid}Ormer Ironbraid{/link}.
• Trabaja en la traducción de la escritura titánica de la {link:goaz-stone}Piedra de Goaz{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra la vida de Whelgar antes de la excavación, ni cuánto tiempo lleva sirviendo a la Liga.]=],
		},
	},
	chapters = {
		{
			title = "La Piedra de Goaz",
			hint = [=[Recupere los fragmentos perdidos de la tablilla del prospector.]=],
			text = [=[Los fragmentos se llamaban Ados, Modr, Golm y Neru, y estaban dispersos por las ruinas de la excavación, entre viejas reliquias y tierra suelta. Cuando encajó el último, Whelgar se inclinó sobre la piedra y empezó a leer. Enseguida le vinieron palabras nuevas, y las pronunció en voz alta: Dioses Antiguos, encadenados bajo la tierra. No dijo lo que temía que significaran. Solo dijo que era el comienzo de algo grande.]=],
		},
	},
	mentions = {
		{ text = "Desenterrar el pasado" },
		{ text = "El prospector despistado" },
		{ text = "En busca del equipo de excavación" },
	},
	bonds = {
		{ id = "merrin-rockweaver", name = "Merrin Rockweaver", note = "una excavadora de su equipo" },
		{ id = "ormer-ironbraid", name = "Ormer Ironbraid", note = "le salvó la vida" },
		{ id = "archaeologist-flagongut", name = "Arqueólogo Flagongut", note = "quiere su fósil" },
	},
})

Translate("esMX", "longbraid-the-grim", {
	title = "Longbraid el Sombrío",
	subtitle = "Comandante del regimiento de Dun Modr",
	found = "El campamento frente a Dun Modr",
	hint = [=[Busque al comandante enano que defiende el campamento frente a la caída Dun Modr.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Longbraid" },
	sections = {
		{
			title = "Resumen",
			text = [=[Longbraid el Sombrío dirigía el regimiento de {link:ironforge}Forjaz{/link} que guardaba {link:dun-modr}Dun Modr{/link} y el {link:thandol-span}Puente Thandol{/link}. Perdió ambos. Los {link:dark-iron-dwarves}Hierro Negro{/link} volaron el puente occidental en una emboscada, y su hermano murió con él. Antes de que el regimiento pudiera reponerse, cayeron sobre el pueblo. Longbraid tocó el cuerno de retirada, y ahora mantiene un pequeño campamento frente a los muros con los pocos que sobrevivieron.]=],
		},
		{
			title = "Importancia",
			text = [=[Longbraid es el dolor y la terquedad de Khaz Modan en un solo {link:dwarves}enano{/link}. No tiene refuerzos, ni aliados de sobra, ni pueblo, y aun así no ha abandonado el camino del norte.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Tocó retirada cuando cayó {link:dun-modr}Dun Modr{/link}, y salvó lo que quedaba de su regimiento.
• Envió al sur, a Menethil, a un jinete con el herido {link:harlo-barnaby}Harlo Barnaby{/link}.
• Da caza al brujo que dirige a los {link:dark-iron-dwarves}Hierro Negro{/link} en {link:wetlands}Los Humedales{/link}.
• Envió a un explorador, el viejo Rustlocke, al puente oriental, y el explorador nunca volvió.]=],
		},
	},
	chapters = {
		{
			title = "La caída de Dun Modr",
			hint = "Traiga noticias del soldado herido de Menethil.",
			text = [=[Longbraid supo que el joven {link:harlo-barnaby}Harlo{/link} había sobrevivido, y por un momento la noticia le dio esperanza. Luego contó el resto sin rodeos. {link:dun-modr}Dun Modr{/link} estaba perdida. El regimiento que la había defendido ya no era más que una sombra de sí mismo.]=],
		},
		{
			title = "Una tarea sombría",
			hint = "Dé caza al brujo que dirige a los Hierro Negro.",
			text = [=[A los {link:dark-iron-dwarves}Hierro Negro{/link} de {link:wetlands}Los Humedales{/link} los dirigía {link:balgaras-the-foul}Balgaras el Inmundo{/link}, un brujo que enviaba a otros a morir y se mantenía fuera de su alcance. Cuando pusieron su oreja ante Longbraid, el comandante no sintió ninguna alegría. Los muertos no volverían. Pero los vivos podrían dormir, y habría que expulsar al resto de los Hierro Negro antes de que llegara un nuevo amo.]=],
		},
	},
	mentions = {
		{ text = "La caída de {link:dun-modr}Dun Modr{/link}" },
		{ text = "Una tarea sombría" },
		{ text = "La furia es profunda, su hermano vengado" },
		{ text = "En busca del equipo de excavación" },
	},
	bonds = {
		{ id = "motley-garmason", name = "Motley Garmason", note = "obligado por honor a permanecer a su lado" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "su oficial" },
		{ id = "harlo-barnaby", name = "Harlo Barnaby", note = "un soldado al que puso a salvo" },
		{ id = "balgaras-the-foul", name = "Balgaras el Inmundo", note = "enemigo" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "planeó la muerte de su hermano" },
	},
})

Translate("esMX", "motley-garmason", {
	title = "Motley Garmason",
	subtitle = "Soldado de Dun Modr",
	found = "El campamento frente a Dun Modr",
	hint = [=[Hable con el enano del campamento de Longbraid que más odia a los Hierro Negro.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Motley" },
	sections = {
		{
			title = "Resumen",
			text = [=[Motley Garmason sirve en el maltrecho regimiento de {link:longbraid-the-grim}Longbraid{/link}. El honor lo obliga a permanecer al lado de su comandante, y eso le irrita. Mientras los soldados de {link:ironforge}Forjaz{/link} luchan por la {link:alliance}Alianza{/link} en tierras lejanas, dice, los propios hogares de los enanos caen ante los {link:dark-iron-dwarves}Hierro Negro{/link}. Quiere que se presione el campamento Hierro Negro con la dureza suficiente para que los refuerzos, si alguna vez llegan, puedan terminar el trabajo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide ataques contra los {link:dark-iron-dwarves}Hierro Negro{/link} del {link:direforge-hill}Cerro Fraguaferoz{/link}.
• Quiere la cabeza de {link:kam-deepfury}Kam Deepfury{/link}, encerrado en las {link:the-stockade}Mazmorras de Ventormenta{/link}, por la muerte del hermano de {link:longbraid-the-grim}Longbraid{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[La guerra contra los {link:dark-iron-dwarves}Hierro Negro{/link}]=],
		},
		{ text = "La furia es profunda" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid el Sombrío", note = "su comandante" },
		{ id = "rhag-garmason", name = "Rhag Garmason", note = "comparte su apellido" },
		{ id = "kam-deepfury", name = "Kam Deepfury", note = "el conspirador al que quiere muerto" },
	},
})

Translate("esMX", "rhag-garmason", {
	title = "Rhag Garmason",
	subtitle = "Soldado de Dun Modr",
	found = "El campamento frente a Dun Modr",
	hint = [=[Hable con el enano del campamento de Longbraid que vigila el Puente Thandol.]=],
	allegiance = "Reino de Forjaz",
	aliases = { "Rhag" },
	sections = {
		{
			title = "Resumen",
			text = [=[Rhag Garmason oyó la explosión que desgarró el {link:thandol-span}Puente Thandol{/link}. Vigila lo que queda del puente desde el campamento de {link:longbraid-the-grim}Longbraid{/link}. Cuando el explorador Ebenezer Rustlocke no volvió, fue Rhag quien descubrió por qué: el viejo {link:dwarves}enano{/link} había muerto en una emboscada, con órdenes {link:dark-iron-dwarves}Hierro Negro{/link} apretadas a su lado. Esas órdenes hablaban de más explosivos esperando al otro lado del desfiladero.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Averiguó el destino del viejo Rustlocke.
• Vio cómo se salvaba el último puente de una segunda explosión.
• Envió una petición de soldados al capitán {link:captain-nials}Nials{/link}, en el {link:refuge-pointe}Refugio de la Zaga{/link}, en las {link:arathi-highlands}Tierras Altas de Arathi{/link}. La respuesta fue no. {link:stromgarde-keep}Stromgarde{/link} había caído, y sus propios soldados tenían una ciudad que recuperar.]=],
		},
	},
	mentions = {
		{ text = "{link:thandol-span}El Puente Thandol{/link}" },
		{ text = "{link:thandol-span}El Puente Thandol{/link}" },
		{ text = "{link:thandol-span}El Puente Thandol{/link}" },
		{ text = "Súplica a la {link:alliance}Alianza{/link}" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid el Sombrío", note = "su comandante" },
		{ id = "motley-garmason", name = "Motley Garmason", note = "comparte su apellido" },
	},
})

Translate("esMX", "roggo-harlbarrow", {
	title = "Roggo Harlbarrow",
	subtitle = "Explorador de Dun Modr",
