	},
})

Translate("esMX", "harlo-barnaby", {
	title = "Harlo Barnaby",
	subtitle = "Soldado herido de Dun Modr",
	found = "Puerto de Menethil",
	hint = "Hable con el soldado herido que despertó en Menethil.",
	allegiance = "Reino de Forjaz",
	aliases = { "Harlo" },
	sections = {
		{
			title = "Resumen",
			text = [=[Harlo Barnaby es un joven soldado del regimiento de {link:longbraid-the-grim}Longbraid{/link}. Mientras los enanos huían de {link:dun-modr}Dun Modr{/link}, un hacha perdida le alcanzó en la espalda y todo se volvió negro. Despertó en el {link:menethil-harbor}Puerto de Menethil{/link}, lejos de los combates, sin saber quién más había sobrevivido. Sus heridas son graves, pero no ha perdido la esperanza. Cree que Longbraid sigue vivo.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide noticias de {link:longbraid-the-grim}Longbraid{/link} y su regimiento.]=],
		},
	},
	mentions = {
		{ text = "La caída de {link:dun-modr}Dun Modr{/link}" },
	},
	bonds = {
		{ id = "longbraid-the-grim", name = "Longbraid el Sombrío", note = "su comandante, que lo puso a salvo" },
	},
})

Translate("esMX", "balgaras-the-foul", {
