Translate("esMX", "rethiel-the-greenwarden", {
	title = "Rethiel el Greenwarden",
	subtitle = "Espíritu del pantano",
	found = "El pantano al este del desvío hacia Dun Modr",
	hint = [=[Busque al espíritu del pantano entre los crocoliscos al este del camino a Dun Modr.]=],
	allegiance = "Los Humedales",
	aliases = { "El Greenwarden", "Rethiel" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Greenwarden es un espíritu del pantano vivo. Los marineros de Menethil hablan de él como de una bestia que parte a los hombres por la mitad de un mordisco. La verdad es más extraña. Tiene muchos nombres y responde a pocos, pero aquellos en quienes confía pueden llamarlo Rethiel. Siente {link:wetlands}Los Humedales{/link} como su propio cuerpo. Dice que la tierra llora por heridas que supuran, y que los pueblos del mundo ya han puesto a prueba su fe antes.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pide que se reduzca el número de gnolls Pellejomusgo, porque se han vuelto demasiados para la tierra.
• Rompe los pedernales de fuego de los gnolls y los arroja al mar.
• Busca devolver al pantano a los reptadores febriles de la cié{link:naga}naga{/link}.]=],
		},
	},
	mentions = {
		{ text = "El Greenwarden" },
		{ text = "Patas que pisotean" },
		{ text = "Tabú del fuego" },
		{ text = "Ampollas en la tierra" },
	},
	bonds = {
		{ id = "first-mate-fitzsimmons", name = "Primer oficial Fitzsimmons", note = "aparta de él a los buscadores" },
	},
})

Translate("esMX", "howin-kindfeather", {
	title = "Howin Kindfeather",
	subtitle = "Jinete de grifo de Los Humedales",
	found = [=[Un campamento junto al camino, al este de la Excavación de Whelgar]=],
	hint = [=[Busque al enano y a su grifo acampados junto al camino, al este de la excavación de Whelgar.]=],
	allegiance = "Clan Martillo Salvaje",
	aliases = { "Howin" },
	sections = {
		{
			title = "Resumen",
			text = [=[Howin Kindfeather acampa junto al camino de {link:wetlands}Los Humedales{/link} con su grifo, Bassbeak. Una vez envió al ave a Menethil con una carta para encargar escamas de cría, algo que todavía maravilla al curtidor del puerto. Escupe cuando habla de los {link:dark-iron-dwarves}Hierro Negro{/link}, de los Faucedraco y de los dracos que montaban, y no logra decidir a quién odia más. Pretende poner las cosas en su sitio. Su plan necesita una capa contra el fuego de dragón, dientes para coserla y un grifo con la barriga llena.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Compra las escamas de las crías carmesíes, que protegen contra el fuego de dragón.
• Reúne dientes y huevos de Faucerrazor para su plan.]=],
		},
	},
	mentions = {
		{ text = "Entrega de la caja carmesí" },
		{ text = "Agujas de Faucerrazor" },
		{ text = "Tiempos difíciles" },
	},
	bonds = {
		{ id = "james-halloran", name = "James Halloran", note = "le vendió las escamas" },
	},
})

Translate("esMX", "hervdana-saegrund", {
	title = "Hervdana Saegrund",
	subtitle = "Chamán de las cascadas del sur",
	found = "Una cueva bajo las cascadas del sur",
	hint = [=[Busque a la chamán cuya familia vive en una cueva bajo las cascadas del sur.]=],
	allegiance = "Chamanes",
	aliases = { "Hervdana" },
	sections = {
		{
			title = "Resumen",
			text = [=[Hervdana Saegrund es una chamán cuya familia vive en una cueva bajo las cascadas del sur de {link:wetlands}Los Humedales{/link}, y entre ellos está Frothrik Saegrund. {link:norric-lochthane}Norric Lochthane{/link} le envía a sus alumnos. Ella enseña que hay que comprender el agua en todas sus formas: dulce donde se encuentra con la salobre, corrompida donde algo oscuro se ha filtrado y pura donde ha reposado intacta durante eras. Sus alumnos recogen agua de {link:redridge-mountains}Crestagrana{/link} y de {link:ashenvale}Vallefresno{/link} antes de volver con Norric.]=],
		},
	},
	mentions = {
		{ text = "La llamada del agua" },
		{ text = "La llamada del agua, al pie de las cascadas" },
		{
			text = [=[La llamada del agua, desde las {link:stonewatch-falls}Cascadas Petravista{/link}]=],
		},
		{ text = "La llamada del agua, desde {link:astranaar}Astranaar{/link}" },
		{
			text = [=[La llamada del agua, de vuelta con {link:norric-lochthane}Norric{/link}]=],
		},
	},
	bonds = {
		{ id = "norric-lochthane", name = "Norric Lochthane", note = "le envía a sus alumnos" },
	},
})

Translate("esMX", "chieftain-nek-rosh", {
	title = "Cacique Nek'rosh",
	subtitle = "Cacique de los Faucedraco",
	found = "Campamento Dentellada",
	hint = [=[Enfréntese al cacique que dirige a los Faucedraco desde su campamento en las colinas orientales.]=],
	allegiance = "Clan Faucedraco",
	aliases = { "Nek'rosh" },
	sections = {
		{
			title = "Resumen",
			text = [=[Nek'rosh es el cacique del {link:dragonmaw-clan}clan Faucedraco{/link} en {link:wetlands}Los Humedales{/link}. Es hijo de Nekros, que dirigió el clan en los años en que tenía cautivos a los dragones rojos. Nekros sometió a los dragones a su voluntad con una magia poderosa. Cuando la magia falló, los dragones se volvieron contra sus amos, y Nekros murió. Su hijo ha jurado vengarse de los dragones que lo mataron.]=],
		},
		{
			title = "Importancia",
			text = [=[Bajo Nek'rosh, un clan destrozado ha vuelto a ser un ejército. Los Faucedraco han entrado en {link:dun-algaz}Dun Algaz{/link}, han construido máquinas de asedio y han puesto la mirada en el {link:menethil-harbor}Puerto de Menethil{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Reunió a los Faucedraco dispersos en el {link:angerfang-encampment}Campamento Dentellada{/link}.
• Lanzó a sus guerreros sobre {link:dun-algaz}Dun Algaz{/link}, cortando el camino entre Menethil y {link:loch-modan}Loch Modan{/link}.
• Construyó catapultas para asediar el {link:menethil-harbor}Puerto de Menethil{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las crónicas de la {link:second-war}Segunda Guerra{/link} hablan de los Faucedraco que retuvieron a la Reina {link:the-drag}Drag{/link}ón en {link:grim-batol}Grim Batol{/link}. Qué papel desempeñó el propio Nek'rosh en aquellos años, no lo dicen.]=],
		},
	},
	chapters = {
		{
			title = "El hijo de Nekros",
			hint = [=[Lleve los estandartes de guerra de los Faucedraco al capitán del Castillo de Menethil.]=],
			text = [=[Cuando pusieron los estandartes ante él, el capitán {link:captain-stoutfist}Stoutfist{/link} contó lo que los enanos sabían de su enemigo. Los Faucedraco ya no eran lo que habían sido cuando montaban dragones. Su cacique era hijo del {link:orcs}orco{/link} que en otro tiempo esclavizó al Vuelo Rojo, y no había olvidado cómo murió su padre.]=],
		},
		{
			title = "Derrotar a Nek'rosh",
			hint = "Queme las catapultas y abata al cacique.",
			text = [=[Primero ardieron las catapultas, y Menethil quedó a salvo de ellas. Luego Nek'rosh cayó en su propio campamento. {link:captain-stoutfist}Stoutfist{/link} lo consideró un golpe decisivo, del que el clan quizá nunca se recuperara.]=],
		},
	},
	mentions = {
		{ text = "Estandartes de guerra" },
		{ text = "La jugada de Nek'rosh" },
		{ text = "Derrotar a Nek'rosh" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Capitán Stoutfist", note = "enemigo" },
		{ id = "ma-ruk-wyrmscale", name = "Ma'ruk Wyrmscale", note = "su señor de la guerra en Dun Algaz" },
		{ id = "alexstrasza", name = "Alexstrasza", note = "reina de los dragones que su padre esclavizó" },
	},
})

Translate("esMX", "ma-ruk-wyrmscale", {
	title = "Ma'ruk Wyrmscale",
	subtitle = "Señor de la guerra Faucedraco",
	found = "Dun Algaz",
	hint = [=[Enfréntese al señor de la guerra Faucedraco que domina el paso de Dun Algaz.]=],
	allegiance = "Clan Faucedraco",
	aliases = { "Ma'ruk" },
	sections = {
		{
			title = "Resumen",
			text = [=[Ma'ruk Wyrmscale es un señor de la guerra del {link:dragonmaw-clan}clan Faucedraco{/link}. Dirige a los orcos que han bajado al paso de {link:dun-algaz}Dun Algaz{/link}, donde tienden emboscadas a todos los viajeros entre {link:loch-modan}Loch Modan{/link} y {link:wetlands}Los Humedales{/link}. Mientras domine el paso, ningún refuerzo llegará por tierra al {link:menethil-harbor}Puerto de Menethil{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Ma'ruk es el filo de la espada de {link:chieftain-nek-rosh}Nek'rosh{/link}. El asedio de Menethil que planea el cacique depende de que él domine el paso.]=],
		},
	},
	bonds = {
		{ id = "chieftain-nek-rosh", name = "Cacique Nek'rosh", note = "su cacique" },
	},
})

Translate("esMX", "dragonmaw-clan", {
	title = "Clan Faucedraco",
	aliases = { "clan Faucedraco", "orcos Faucedraco" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Faucedraco son un clan de {link:orcs}orcos{/link} de la antigua {link:horde}Horda{/link}. En la {link:second-war}Segunda Guerra{/link} hicieron lo que ningún otro clan pudo: convirtieron a los dragones rojos en sus siervos. Desde su bastión de {link:grim-batol}Grim Batol{/link} mantuvieron cautiva a {link:alexstrasza}Alexstrasza{/link}, la Reina {link:the-drag}Drag{/link}ón, gracias al poder de un artefacto que había forjado {link:deathwing}Alamuerte{/link}, y criaron a sus crías como monturas de guerra. Dragones rojos montados por orcos Faucedraco quemaron los barcos de la {link:alliance}Alianza{/link} en el mar.]=],
		},
		{
			title = "La caída",
			text = [=[La magia que ataba a los dragones falló. El Vuelo Rojo se volvió contra el clan y le dio caza sin piedad. Nekros, que había dirigido a los Faucedraco, murió, y el clan quedó casi destruido. Los pocos que sobrevivieron huyeron de {link:grim-batol}Grim Batol{/link} y se escondieron en las montañas al este del camino de {link:wetlands}Los Humedales{/link}.]=],
		},
		{
			title = "En estos días",
			text = [=[Los Faucedraco han vuelto a hacerse fuertes bajo el cacique {link:chieftain-nek-rosh}Nek'rosh{/link}, hijo de Nekros. Desde el {link:angerfang-encampment}Campamento Dentellada{/link} y el oculto {link:dragonmaw-retreat}Dragonmaw Retreat{/link} atacan hacia el oeste, y se han apoderado del paso de {link:dun-algaz}Dun Algaz{/link}. Construyen catapultas, reúnen armas y, según se susurra, todavía sueñan con dragones. Los enanos de Menethil los consideran feroces, pero saben que el clan sin sus dragones es una amenaza menor que el clan que en otro tiempo oscureció el cielo.]=],
		},
	},
})

Translate("esMX", "third-fleet", {
	title = "Tercera Flota",
	aliases = { "La Tercera Flota", "la Flota Condenada" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Tercera Flota de {link:kul-tiras}Kul Tiras{/link} navegó en la {link:second-war}Segunda Guerra{/link}, la última gran guerra contra la {link:horde}Horda{/link}. Sus barcos venían de las costas de {link:lordaeron}Lordaeron{/link}, y al menos una nave que no era suya se unió a ella en busca de protección: el {i}Flying Osprey{/i}, que llevaba un cargamento de hierro forjaluz. Frente a la costa de {link:wetlands}Los Humedales{/link}, orcos montados en dragones rojos cayeron sobre la flota. Los barcos ardieron y se hundieron, y sus restos aún yacen a lo largo de la costa noroeste, en el lugar llamado {link:the-lost-fleet}La Flota Perdida{/link}.]=],
		},
		{
			title = "La maldición",
			text = [=[Algo se escondía a bordo del {i}Intrepid{/i}: un Ojo de Paleth maldito, guardado bajo llave en el cofre del capitán. Los Ojos los hicieron sacerdotes humanos para que brillaran con luz sagrada, pero este había presenciado demasiado dolor. Su poder retiene a las tripulaciones ahogadas en sus cascos podridos. Solo un hombre de la flota sigue vivo, el primer oficial {link:first-mate-fitzsimmons}Fitzsimmons{/link}, y bebe en Menethil para no soñar con ellos.]=],
		},
		{
			title = "La carga",
			text = [=[Los múrlocs de la costa han saqueado el {i}Flying Osprey{/i}. Sus lingotes de hierro forjaluz son muy apreciados por quienes luchan contra los no-muertos. Una elfa de la noche de {link:teldrassil}Teldrassil{/link}, {link:sylessa-duskwhisper}Sylessa Duskwhisper{/link}, dice que el barco también llevaba Nord'el, una flor del {link:mount-hyjal}Monte Hyjal{/link}.]=],
		},
	},
})

Translate("esMX", "goaz-stone", {
	title = "Piedra de Goaz",
	aliases = { "La Piedra de Goaz" },
	sections = {
		{
			title = "Resumen",
			text = [=[La Piedra de Goaz es una gran tablilla que el prospector {link:prospector-whelgar}Whelgar{/link} desenterró en su excavación de {link:wetlands}Los Humedales{/link}, justo antes de que los raptores la arrasaran. Está tallada en la escritura de los titanes. Cuando la encontraron, estaba rota en cuatro partes, y los fragmentos perdidos llevaban los nombres de Ados, Modr, Golm y Neru. Incluso incompleta, la tablilla hablaba de un plan divino y de una profecía condenada.]=],
		},
		{
			title = "La lectura",
			text = [=[Cuando se restauraron los cuatro fragmentos, {link:prospector-whelgar}Whelgar{/link} comenzó el lento trabajo de la traducción. Las primeras palabras nuevas que leyó hablaban de Dioses Antiguos, encadenados bajo la tierra. La {link:explorers-league}Liga de Expedicionarios{/link} ya había encontrado tallas titánicas antes, pero rara vez alguna que hablara tan claramente de lo que yace debajo.]=],
		},
		{
			title = "El presente",
			text = [=[{link:prospector-whelgar}Whelgar{/link} no ha terminado su lectura. Por encima de su excavación, en las colinas, una niebla ha empezado a bajar de las montañas y los constructos de los titanes vuelven a caminar. La Liga aún no sabe si la piedra y el despertar de las tierras altas están unidos.]=],
		},
	},
})
